SELECT c.id, c.instructor_id, 'Design Quiz 1: Foundations', TIMESTAMPADD(SECOND, -3, UTC_TIMESTAMP(6))
FROM learnhub_course.courses c
WHERE c.title = 'Graphic Design Fundamentals'
  AND NOT EXISTS (SELECT 1 FROM learnhub_assessment.assessments a WHERE a.course_id = c.id AND a.title = 'Design Quiz 1: Foundations');
SET @quiz = (SELECT a.id FROM learnhub_assessment.assessments a JOIN learnhub_course.courses c ON a.course_id = c.id
             WHERE c.title = 'Graphic Design Fundamentals' AND a.title = 'Design Quiz 1: Foundations');

